head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf25700";
scwin.rownum = 0;
scwin.chgSeq = 900;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf25700.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb4", fn: function () { return String(dma_bndInfo.get("isuAmt")) + " 원"; } },
        { childId: "__rb6", fn: function () { return String(dma_bndInfo.get("listAmt")) + " 원"; } },
        { childId: "__rb7", fn: function () { return String(dma_bndInfo.get("bfchgCoupnRt")) + " %"; } },
        { childId: "__rb13", fn: function () { return String(dma_bndInfo.get("spdSgn")) + " " + String(dma_bndInfo.get("spd")) + "%"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.getBdchrgInfo($c.util.getComponent('slc_bdchrgTpCd'));
        clickedRow = null;
        $("#tbl_schdl").on("click", "tr", function() {
                clickedRow = $(this);
                $("tr").removeClass("on");
                $(this).addClass("on");
                const frnids_chg_tp_cd = $(this).find("input[name='frnids_chg_tp_cd']").val();
                if (frnids_chg_tp_cd === "D") {
                    $c.util.getComponent('txt_delRow').setLabel("삭제취소");
                } else {
                    $c.util.getComponent('txt_delRow').setLabel("일정삭제");
                }
        });
        $("#txt_addRow").click(async function() {
                if (clickedRow) {
                    const can_add_row = clickedRow.find("input[name='canAddRow']").val();
                    if (can_add_row != null && can_add_row === "N") {
                        await $c.win.alert("신고완료된 일정 중간에는 행추가 할 수 없습니다.");
                        return;
                    }
                    scwin.addSchdl(clickedRow);
                } else {
                    await $c.win.alert("행추가할 위치를 선택하세요.\n선택 된 행의 아래에 새로운 행이 추가됩니다.");
                }
        });

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Apply();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name btn_DelSchdl1_onclick
 * @description btn_DelSchdl1 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_DelSchdl1_onclick = async function(e){
    try {
        await scwin.delSchdl1()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_DelSchdl1_onclick' }); }
};

/**
 * @method
 * @name slc_bdchrgTpCd_onchange
 * @description slc_bdchrgTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_bdchrgTpCd_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.getBdchrgInfo(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.slc_bdchrgTpCd_onchange' }); }
};

/**
 * @method
 * @name btn_fileBrowse_onclick
 * @description btn_fileBrowse 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileBrowse_onclick = function(e){
    try {
        scwin.file_browse()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_fileBrowse_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delRow_onclick = async function(e){
    try {
        await scwin.delRow()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name btn_Apply_onclick
 * @description btn_Apply 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Apply_onclick = async function(e){
    try {
        await scwin.apply()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_Apply_onclick' }); }
};

/**
 * @method
 * @name btn_goToList_onclick
 * @description btn_goToList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goToList_onclick = function(e){
    try {
        goToList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_goToList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Apply
 * @description Apply 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Apply = async function () {
    const sbmOptions = {
        id: "tx_fn_Apply",
        method: "post",
        action: "/event/frnidsChg.do",
        ref: "dma_ApplyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_GetBdchrgInfo
 * @description Get Bdchrg Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetBdchrgInfo = async function () {
    const sbmOptions = {
        id: "tx_fn_GetBdchrgInfo",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_GetBdchrgInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cal_offMask
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @returns {void}
 * @hidden N
 */
scwin.cal_offMask = function () { /* 등가 no-op — to-be 필드 마스크 미사용 */ };

/**
 * @method
 * @name calcBasInt
 * @description calc Bas Int 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcBasInt = async function () {
    const fm = (document.SendForm || { elements: [] });
    let sum = 0;
    if (fm.spd_sgn.value === '+') {
        sum = parseFloat(fm.nxtpd_bas_int.value) + parseFloat(fm.spd.value);
    } else {
        if (parseFloat(fm.nxtpd_bas_int.value) < parseFloat(fm.spd.value)) {
            await $c.win.alert("가산금리부호가 '-'인 경우, 기준금리를 가산금리 보다 크게 입력하세요.");
            fm.spd_sgn.value = '+';
            return;
        }
        sum = parseFloat(fm.nxtpd_bas_int.value) - parseFloat(fm.spd.value);
    }
    if (sum >= 100) {
        await $c.win.alert("기준금리와 가산금리의 합은 '100 미만'으로 입력하세요.");
        fm.nxtpd_bas_int.value = '';
        nxtpd_bas_int.focus();
        return;
    }
    const fix_sum = sum.toFixed(5);
    fm.bas_int.value = fix_sum.replace(/0+$/, "");
};

/**
 * @method
 * @name apply
 * @description apply 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.apply = async function () {
    if (!await scwin.chkData()) {
        return false;
    }
    const form = (document.SendForm || { elements: [] });
    if (!await $c.win.confirm("신청하시겠습니까?")) {
        return false;
    }
    $c.util.getComponent('dma_ApplyReq').set('method', "requestFrnidsChange");
    form.action = "/event/frnidsChg.do";
    form.target = "_self";
    await scwin.tx_fn_Apply();
};

/**
 * @method
 * @name chkData
 * @description chk Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkData = async function () {
    let hasFixddVal = false;
    for (let __r = 0, __n = $c.util.getComponent('dlt_schdlList').getRowCount(); __r < __n; __r++) {
        if ($c.util.getComponent('dlt_schdlList').getCellData(__r, 'afchgIntFixDd').trim() !== '') {
            hasFixddVal = true;
        }
    }
    let hasPayddVal = false;
    for (let __r = 0, __n = $c.util.getComponent('dlt_schdlList').getRowCount(); __r < __n; __r++) {
        if ($c.util.getComponent('dlt_schdlList').getCellData(__r, 'afchgIntPayDd').trim() !== '') {
            hasPayddVal = true;
        }
    }
    let hasDeletedVal = false;
    /* 수동 전환 필요: 이름 선택자 순회 [name=frnids_chg_tp_cd] — S1 대응 열 없음 · to-be 에 돌 요소가 없다 */ $('input[name=frnids_chg_tp_cd]').each(function() {
            if ($(this).val().trim() === 'D') {
                hasDeletedVal = true;
            }
    });
    if (hasFixddVal === false && hasPayddVal === false && hasDeletedVal === false) {
        await $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }
    const attach_file = document.getElementsByName("chk");
    for (let i = 0; i < attach_file.length; i++) {
        if ($("input[name='attach_file_nm[" + i + "]']").val() === "") {
            await $c.win.alert("첨부파일을 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    return true;
};

/**
 * @method
 * @name file_browse
 * @description file browse 처리
 * @returns {void}
 * @hidden N
 */
scwin.file_browse = function () { $c.util.onUploadClick($c.util.getComponent('mpd_files')); };

/**
 * @method
 * @name addRow1
 * @description add Row1 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRow1 = function () {
    const rowPlus = $c.util.getComponent("tbl_file");
    let tr;
    let th;
    let td;
    const newRowNum = scwin.rownum + 1;
    if (scwin.rownum === 0) {
        rowPlus.deleteRow(0);
    }
    const $tblFile = $('#tbl_file');
    const $tr = $("<tr></tr>");
    const $td1 = $("<td><input type=\"checkbox\" name=\"chk\" /></td>").addClass('first txc');
    const $td2 = $("<td><input type=\"text\" name=\"attach_file_nm[" + scwin.rownum + "]\" readonly style=\"width: 500px; height:20px; vertical-align: 6px;\" class=\"file_input_textbox\" /><div class=\"file_input_div\"><img src=\"/images/btn_find.gif\" name=\"file_1\" class=\"file_input_img_btn\" alt=\"open\" /><input type=\"file\" name=\"attachFiles[" + scwin.rownum + "]\" style=\"width:91px; height:20px; \" onchange=\"fn_getFileNm(" + scwin.rownum + ");\" class=\"file_input_hidden\" /></div></td>");
    $tr.append($td1);
    $tr.append($td2);
    $tblFile.append($tr);
    scwin.rownum++;
    reNames();
};

/**
 * @method
 * @name delRow
 * @description del Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delRow = async function () {
    const rowPlus = $c.util.getComponent("tbl_file");
    let chk_num = 0;
    const isCheckedMandatoryFile = false;
    if (scwin.rownum > 0) {
        $i = 0;
        /* 수동 전환 필요: 이름 선택자 순회 [name=chk] — B3/B4 스펙 참조 없음(as-is 대조 필요) · to-be 에 돌 요소가 없다 */ $('input[name=chk]').each(function() {
                if ($(this).is(":checked")) {
                    chk_num++;
                    rowPlus.deleteRow($i);
                    scwin.rownum--;
                    $i = $i - 1;
                    if (scwin.rownum === 0) {
                        let tr;
                        let th;
                        let td;
                        const newRowNum = scwin.rownum + 1;
                        tr = rowPlus.insertRow();
                        tr.className = "first";
                        td = tr.insertCell();
                        td.colSpan = "2";
                        td.className = "first txc";
                        td.innerHTML = "첨부파일이 없습니다.";
                        td.appendChild(td);
                    }
                }
                $i = $i + 1;
        });
        if (chk_num === 0) {
            await $c.win.alert("선택된 행이 없습니다.");
            return;
        }
        reNames();
    } else {
        if (scwin.rownum < 1) {

        }
    }
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo != null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_telNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_telNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_telNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_telNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

